{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Tolbutamide, a p-toluenesulfonylurea closely related to the query's sulfonylurea core, has an absolute oral bioavailability of 85% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Glimepiride, another sulfonylurea antidiabetic with a p-toluenesulfonyl group, is essentially completely bioavailable (97%) after oral tablet dosing in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Levosulpiride, a polar sulfonamide with a basic amine, has an absolute oral bioavailability of 23.4% in humans, which is above the 20% threshold and supports high F despite poor permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Sulpiride, structurally similar in its ionizable sulfonamide/amine character, has an absolute oral bioavailability of about 34%, again above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Tolperisone has very low oral bioavailability in humans, but its structure lacks the sulfonylurea/sulfonamide acid-amine motif and has low similarity to the query, providing weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar, ionizable sulfonylurea/hydrazide with a low physicochemical permeability prior, but direct human data for sulfonylurea analogues (tolbutamide, glimepiride) show high F, and even polar sulfonamide-basic amine analogues (sulpiride/levosulpiride) exceed 20%. The only sub-20% analogue is structurally distant. Therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query scaffold.",
    "The effect of the hydrazide and bicyclic amine on permeability and first-pass metabolism is not directly measured.",
    "Transporter-mediated absorption or efflux behavior is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

